import React, { useEffect, useRef, useState } from "react";
import { CronExpressionParser } from "cron-parser";
import { ArchiveRestore, Bot, Check, CircleAlert, Copy, ExternalLink, FileText, Link2, Play, Plus, RefreshCw, Settings2, Square, X } from "lucide-react";
import { BotCreateDialog } from "./BotCreateDialog.jsx";
import { BotIcon, BotIconPicker, DEFAULT_BOT_ICON } from "./BotIcon.jsx";

const STATE_LABELS = { healthy: "Healthy", on_schedule: "On schedule", running: "Running", degraded: "Degraded", offline: "Offline", overdue: "Overdue", unknown: "Unknown", paused: "Paused", manual: "Manual" };
const STATE_ORDER = { overdue: 0, offline: 1, degraded: 2, unknown: 3, paused: 4, running: 5, healthy: 6, on_schedule: 6, manual: 7 };
const EVENT_LABELS = { status_check_succeeded: "Status check succeeded", status_check_failed: "Status check failed", state_changed: "State changed", bot_became_stale: "Bot became stale", platform_identity_verified: "Platform identity verified", job_scheduled: "Job scheduled", job_started: "Job started", job_succeeded: "Job succeeded", job_failed: "Job failed", job_skipped: "Job skipped", job_cancelled: "Job cancelled", job_became_overdue: "Job became overdue", configuration_updated: "Configuration updated", monitoring_paused: "Monitoring paused", monitoring_resumed: "Monitoring resumed" };
const SCHEDULER_SOURCES = ["Internal bot scheduler", "Windows Task Scheduler", "GitHub Actions", "Hosting-provider cron", "External automation", "Manual", "Unknown"];
const BOT_PERMISSION_OPTIONS = [["read_notes", "Read notes"], ["write_notes", "Edit notes"], ["projects", "Use projects"], ["skills", "Run skills"]];

function exactTime(value, timezone) {
  if (!value) return "Never";
  const date = new Date(value); if (Number.isNaN(date.getTime())) return "Invalid time";
  return new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short", timeZone: timezone || undefined }).format(date);
}
function relativeTime(value, reference = new Date()) {
  if (!value) return "Never";
  const difference = new Date(value).getTime() - reference.getTime();
  if (!Number.isFinite(difference)) return "Unknown";
  const absolute = Math.abs(difference); let divisor = 1000; let unit = "second";
  if (absolute >= 86_400_000) { divisor = 86_400_000; unit = "day"; }
  else if (absolute >= 3_600_000) { divisor = 3_600_000; unit = "hour"; }
  else if (absolute >= 60_000) { divisor = 60_000; unit = "minute"; }
  return new Intl.RelativeTimeFormat(undefined, { numeric: "auto" }).format(Math.round(difference / divisor), unit);
}
function stateOf(bot) { return bot?.derivedState?.state || "unknown"; }
function platformLabel(platforms = []) { return platforms.map((value) => value === "notebook" ? "Notebook" : value === "discord" ? "Discord" : "Telegram").join(" + ") || "Not configured"; }
function stateBadge(bot) {
  if (bot?.platforms?.includes("notebook")) return <span className="bot-state state-healthy">Ready</span>;
  const state = stateOf(bot);
  return <span className={`bot-state state-${state}`}>{STATE_LABELS[state] || state}</span>;
}
function makeId() { return globalThis.crypto?.randomUUID?.() || `local-${Date.now()}-${Math.random().toString(36).slice(2)}`; }
function defaultMonitoring() { return { adapter: "manual", url: "", filePath: "", httpMethod: "GET", authSecretRef: "", intervalSeconds: 60, timeoutMilliseconds: 5000, staleAfterSeconds: 180, failuresBeforeOffline: 3, monitoringEnabled: true, expectedResponseCode: "" }; }
function defaultConnection(platform) { return { id: makeId(), platform, externalBotId: "", username: "", displayName: "", avatarUrl: "", credentialSecretRef: "", credentialState: "not_configured", credentialVerifiedAt: null, credentialErrorSummary: "", installPermissions: "0", verificationMode: "token" }; }
function defaultJob(timezone) { return { id: makeId(), name: "", description: "", scheduleType: "cron", cronExpression: "0 9 * * *", intervalSeconds: 3600, oneTimeAt: "", timezone, enabled: true, critical: false, schedulerSource: "Unknown", schedulerUrl: "", expectedDurationSeconds: 300, gracePeriodSeconds: 600, retryDescription: "", authoritativeNextRunAt: "", logsLocation: "", archivedAt: null }; }
function defaultCommand(platform = "discord") { return { id: makeId(), platform, command: "", description: "", usage: "", parameters: "", permission: "", category: "General", enabled: true, deprecated: false, notes: "" }; }
function newDraft() {
  const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  return { name: "", description: "", icon: DEFAULT_BOT_ICON, platforms: ["discord"], executionMode: "continuous", environment: "development", enabled: true, tags: [], repositoryUrl: "", localProjectPath: "", deploymentUrl: "", hostingProvider: "", runtime: "", version: "", logsLocation: "", schedulerSource: "Unknown", schedulerUrl: "", monitoring: defaultMonitoring(), connections: [defaultConnection("discord")], jobs: [], commands: [], skillIds: [], timezone };
}
function editableBot(bot) {
  if (!bot) return newDraft();
  const copy = structuredClone(bot);
  delete copy.runtime; delete copy.derivedState; delete copy.archivedAt; delete copy.createdAt; delete copy.updatedAt;
  copy.runtime = bot.runtimeLanguage || "";
  copy.monitoring = { ...defaultMonitoring(), ...(copy.monitoring || {}) };
  copy.icon = copy.icon || DEFAULT_BOT_ICON;
  copy.connections = copy.connections || []; copy.jobs = copy.jobs || []; copy.commands = copy.commands || [];
  copy.tags = copy.tags || []; copy.skillIds = copy.skillIds || [];
  return copy;
}
function cronPreview(job) {
  if (job.scheduleType === "manual") return { label: "Manual", values: [] };
  if (job.scheduleType === "external") return { label: job.authoritativeNextRunAt ? "Reported externally" : "Externally scheduled", values: job.authoritativeNextRunAt ? [job.authoritativeNextRunAt] : [] };
  if (job.scheduleType === "oneTime") return { label: "One time", values: job.oneTimeAt ? [job.oneTimeAt] : [] };
  if (job.scheduleType === "interval") {
    const seconds = Number(job.intervalSeconds); if (!(seconds > 0)) throw new Error("Enter a positive interval.");
    const start = Date.now(); return { label: `Every ${seconds} seconds`, values: [1, 2, 3].map((step) => new Date(start + step * seconds * 1000).toISOString()) };
  }
  if (!job.timezone) throw new Error("Timezone required.");
  const expression = CronExpressionParser.parse(job.cronExpression || "", { currentDate: new Date(), tz: job.timezone });
  return { label: job.cronExpression, values: expression.take(3).map((date) => date.toISOString()) };
}

export function BotSidebar({ bots, currentId, onSelect }) {
  const active = bots.filter((bot) => !bot.archivedAt);
  return <div className="bot-sidebar-list" aria-label="Bot registry shortcuts">
    {active.map((bot) => <button key={bot.id} className={currentId === bot.id ? "active" : ""} onClick={() => onSelect(bot.id)}><BotIcon icon={bot.icon} name={bot.name} size="small" /><span><strong>{bot.name}</strong><small>{bot.platforms?.includes("notebook") ? "Ready · Notebook" : `${STATE_LABELS[stateOf(bot)] || "Unknown"} · ${bot.executionMode}`}</small></span></button>)}
  </div>;
}

function AttentionArea({ bots, onOpen }) {
  const issues = bots.filter((bot) => !bot.archivedAt).flatMap((bot) => {
    const state = stateOf(bot); const items = [];
    if (["degraded", "offline", "overdue"].includes(state)) items.push({ bot, text: bot.derivedState?.reason || `${STATE_LABELS[state]} status requires attention.` });
    else if (state === "unknown") items.push({ bot, text: bot.derivedState?.reason || "No trustworthy health evidence is available." });
    if (bot.runtime?.isStale) items.push({ bot, text: "Status data is stale; the last useful observation is retained." });
    for (const connection of bot.connections || []) if (connection.credentialState === "invalid") items.push({ bot, text: `${connection.platform === "discord" ? "Discord" : "Telegram"} identity verification failed: ${connection.credentialErrorSummary || "invalid credential"}` });
    return items;
  }).slice(0, 8);
  if (!issues.length) return null;
  return <section className="bots-attention"><header><CircleAlert size={15} aria-hidden="true" /><strong>Needs attention</strong><span>{issues.length}</span></header>{issues.map((issue, index) => <button key={`${issue.bot.id}-${index}`} onClick={() => onOpen(issue.bot.id)}><strong>{issue.bot.name}</strong><span>{issue.text}</span><em>Open</em></button>)}</section>;
}

function UpcomingJobs({ upcoming, onOpen, limit = 5 }) {
  return <section className="upcoming-jobs"><header><div><span className="section-kicker">Across all bots</span><h2>Upcoming jobs</h2></div><span>{upcoming.length ? `${Math.min(limit, upcoming.length)} shown` : "No scheduled jobs"}</span></header>
    <div className="upcoming-list">{upcoming.slice(0, limit).map((item) => <button key={`${item.botId}-${item.job.id}`} onClick={() => onOpen(item.botId)}><span className={`platform-mark ${item.platforms?.[0] || "unknown"}`}>{item.platforms?.[0] === "telegram" ? "T" : "D"}</span><span><strong>{item.job.name}</strong><small>{item.botName} · {item.job.schedulerSource || "Unknown source"}</small></span><span><strong>{relativeTime(item.nextRunAt)}</strong><small>{exactTime(item.nextRunAt, item.job.timezone)} · {item.job.timezone}</small></span><span className={`calculation ${item.nextRunSource}`}>{item.nextRunSource}</span><span className={`job-health state-${item.health?.state || "unknown"}`}>{STATE_LABELS[item.health?.state] || "Unknown"}</span></button>)}</div>
    {!upcoming.length && <p className="bots-section-empty">Event-driven, external without a reported next time, or no scheduled jobs.</p>}
  </section>;
}

function BotRegistry({ bots, upcoming, onOpen, onAdd }) {
  const [query, setQuery] = useState(""); const [view, setView] = useState("active");
  const filtered = bots.filter((bot) => {
    const haystack = [bot.name, bot.description, ...(bot.tags || []), ...(bot.connections || []).flatMap((connection) => [connection.username, connection.displayName]), ...(bot.jobs || []).map((job) => job.name), ...(bot.commands || []).flatMap((command) => [command.command, command.description])].join(" ").toLowerCase();
    if (query && !haystack.includes(query.toLowerCase())) return false;
    if (view === "all") return true;
    if (view === "archived") return Boolean(bot.archivedAt);
    if (bot.archivedAt) return false;
    if (view === "attention") return ["overdue", "offline", "degraded", "unknown"].includes(stateOf(bot));
    if (["notebook", "discord", "telegram"].includes(view)) return bot.platforms?.includes(view);
    return true;
  }).sort((left, right) => (STATE_ORDER[stateOf(left)] ?? 9) - (STATE_ORDER[stateOf(right)] ?? 9));
  return <section className="bot-registry"><header><div><span className="section-kicker">Your Bots</span><h2>{filtered.length} {filtered.length === 1 ? "Bot" : "Bots"}</h2></div></header>
    <div className="bot-filters"><label className="filter-search"><span aria-hidden="true">⌕</span><input type="search" name="bot-search" autoComplete="off" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search bots…" aria-label="Search bots" /></label><label className="filter-view"><span>View</span><select name="bot-view" value={view} onChange={(event) => setView(event.target.value)} aria-label="Bot view"><option value="active">Active</option><option value="attention">Needs attention</option><option value="notebook">Notebook bots</option><option value="discord">Discord</option><option value="telegram">Telegram</option><option value="archived">Archived</option><option value="all">All</option></select></label></div>
    {filtered.length ? <div className="bot-list" aria-label="Bots">{filtered.map((bot) => { const next = upcoming.find((item) => item.botId === bot.id); return <button className="bot-list-row" key={bot.id} onClick={() => onOpen(bot.id)}><BotIcon icon={bot.icon} name={bot.name} /><span className="bot-list-identity"><strong>{bot.name}</strong><small>{(bot.connections || []).map((connection) => connection.username ? `@${connection.username}` : connection.displayName).filter(Boolean).join(" · ") || platformLabel(bot.platforms)}</small><em>{bot.description || "No description yet."}</em></span><span className="bot-list-status">{stateBadge(bot)}<small>{bot.derivedState?.reason || "No status evidence yet."}</small></span><span className="bot-list-next"><strong>{next ? relativeTime(next.nextRunAt) : "No upcoming job"}</strong><small>{next ? next.job.name : bot.executionMode}</small></span><span className="bot-list-open" aria-hidden="true">→</span></button>; })}</div> : <div className="bot-empty compact"><strong>{bots.length ? "No Matching Bots" : "Create Your First Bot"}</strong><span>{bots.length ? "Change the search or view." : "Choose a name, logo, and permissions. Notebook creates the bot and private link instantly."}</span>{!bots.length && <button onClick={onAdd}><Plus size={14} aria-hidden="true" /> Create Bot</button>}</div>}
  </section>;
}

function DetailField({ label, value, action }) { return <div className="bot-detail-field"><span>{label}</span><strong>{value || "Not configured"}</strong>{action}</div>; }

function BotDetails({ bot, api, notes, upcoming, onBack, onEdit, onChanged, onOpenNote }) {
  const localManaged = bot.platforms?.includes("notebook");
  const notebookLinked = localManaged || bot.tags?.includes("notebook-managed");
  const [tab, setTab] = useState("overview"); const [activity, setActivity] = useState([]); const [processState, setProcessState] = useState(null); const [botLink, setBotLink] = useState(""); const [busy, setBusy] = useState(""); const [message, setMessage] = useState("");
  async function loadActivity() { setActivity(await api.bots.activity(bot.id)); }
  async function loadProcess() { try { setProcessState(await api.bots.processStatus(bot.id)); } catch { setProcessState({ available: false, running: false }); } }
  useEffect(() => { let active = true; Promise.all([api.bots.activity(bot.id), api.bots.processStatus(bot.id).catch(() => ({ available: false, running: false })), notebookLinked ? api.bots.link(bot.id).catch(() => ({ url: "" })) : Promise.resolve({ url: "" })]).then(([events, process, privateLink]) => { if (active) { setActivity(events); setProcessState(process); setBotLink(privateLink.url || ""); } }).catch(() => setMessage("Bot details could not be loaded.")); return () => { active = false; }; }, [bot.id, notebookLinked]);
  async function check() { setBusy("check"); setMessage("Checking status…"); try { const result = await api.bots.check(bot.id); await Promise.all([onChanged(), loadActivity(), loadProcess()]); setMessage(result.skipped ? "No automatic check is configured. Open Advanced Settings to add one." : result.ok ? `Check succeeded in ${result.snapshot.responseLatencyMilliseconds} ms.` : result.error.message); } catch (error) { setMessage(error.message || "Check failed. Review the connection in Settings."); } finally { setBusy(""); } }
  async function toggleProcess() { setBusy("process"); setMessage(processState?.running ? "Stopping bot…" : "Starting bot…"); try { const result = processState?.running ? await api.bots.stopProcess(bot.id) : await api.bots.startProcess(bot.id); setProcessState(result); setMessage(result.running ? "Bot is running while Notebook remains open." : "Bot stopped."); } catch (error) { setMessage(error.message || "The local bot process could not be changed. Check the project log."); } finally { setBusy(""); } }
  async function verify(connection) { setBusy(connection.id); setMessage("Verifying identity…"); try { const result = await api.bots.verifyConnection(bot.id, connection.id); await onChanged(); setMessage(result.credentialState === "verified" ? "Identity verified." : result.credentialErrorSummary); } catch (error) { setMessage(error.message || "Verification failed. Check the saved key."); } finally { setBusy(""); } }
  async function copyBotLink() { try { await api.clipboard.writeText(botLink); setMessage("Bot link copied."); } catch { setMessage("The bot link could not be copied."); } }
  async function resetBotLink() { if (!confirm("Reset this bot link? The old link will stop working.")) return; setBusy("link"); try { const result = await api.bots.resetLink(bot.id); setBotLink(result.url); setMessage("Bot link reset. The old link no longer works."); await loadActivity(); } catch (error) { setMessage(error.message || "The bot link could not be reset."); } finally { setBusy(""); } }
  async function archive() { if (!confirm(`${bot.archivedAt ? "Restore" : "Archive"} “${bot.name}”?${bot.archivedAt ? "" : " Checks stop; documentation and history stay."}`)) return; setBusy("archive"); try { if (bot.archivedAt) await api.bots.restore(bot.id); else await api.bots.archive(bot.id); await onChanged(); } finally { setBusy(""); } }
  const note = notes.find((item) => item.id === bot.documentationNoteId);
  async function openDocumentation() { const currentNote = note || (await api.notes.list()).find((item) => item.id === bot.documentationNoteId); if (!currentNote) { setMessage("The runbook could not be found."); return; } onOpenNote(currentNote); }
  const botUpcoming = upcoming.filter((item) => item.botId === bot.id); const next = botUpcoming[0];
  return <div className="bot-details"><header className="bot-details-header"><button type="button" className="bot-back" onClick={onBack}>← Bots</button><div><BotIcon icon={bot.icon} name={bot.name} size="large" /><span><h1>{bot.name}</h1><p>{platformLabel(bot.platforms)} · {bot.environment}</p></span></div><div className="bot-details-actions">{processState?.available && <button type="button" onClick={toggleProcess} disabled={busy === "process"}>{processState.running ? <Square size={12} aria-hidden="true" /> : <Play size={13} aria-hidden="true" />} {busy === "process" ? "Working…" : processState.running ? "Stop" : "Start"}</button>}{!localManaged && <button type="button" onClick={check} disabled={busy === "check"}><RefreshCw size={13} className={busy === "check" ? "spin" : ""} aria-hidden="true" /> {busy === "check" ? "Checking…" : "Check Now"}</button>}</div></header>
    <div className="bot-truth-row">{localManaged ? <span className="bot-state state-healthy">Ready</span> : stateBadge(bot)}<span><strong>{localManaged ? "Managed in Notebook." : bot.derivedState?.reason || "No status evidence yet."}</strong><small>{localManaged ? `${bot.permissions?.length || 0} permissions · private link active` : processState?.running ? "Local process running" : bot.runtime?.lastCheckedAt ? `Checked ${relativeTime(bot.runtime.lastCheckedAt)}` : "Never checked"}</small></span></div>
    {message && <p className="bot-message" role="status" aria-live="polite">{message}</p>}
    <nav className="bot-tabs" aria-label="Bot details sections">{["overview", "activity", "settings"].map((value) => <button type="button" key={value} className={tab === value ? "active" : ""} aria-pressed={tab === value} onClick={() => setTab(value)}>{value[0].toUpperCase() + value.slice(1)}</button>)}</nav>
    <div className="bot-detail-scroll">
      {tab === "overview" && <>{localManaged ? <section className="bot-overview-grid compact"><DetailField label="Status" value="Ready" /><DetailField label="Access" value={`${bot.permissions?.length || 0} permissions`} /><DetailField label="Link" value="Private · active" /><DetailField label="Location" value="Notebook" /></section> : <section className="bot-overview-grid compact"><DetailField label="Status" value={STATE_LABELS[stateOf(bot)]} /><DetailField label="Last Check" value={bot.runtime?.lastCheckedAt ? relativeTime(bot.runtime.lastCheckedAt) : "Never"} /><DetailField label="Next Job" value={next ? `${next.job.name} · ${relativeTime(next.nextRunAt)}` : "None scheduled"} /><DetailField label="Runtime" value={[bot.runtimeLanguage || "", bot.runtime?.reportedVersion || bot.version].filter(Boolean).join(" · ") || "Not reported"} /></section>}<section className="bot-copy-card"><h2>Purpose</h2><p>{bot.description || "No description yet."}</p>{Boolean(bot.tags?.length) && <div className="tag-row">{bot.tags.map((value) => <span key={value}>{value}</span>)}</div>}</section>{Boolean(botUpcoming.length) && <section className="bot-overview-section"><header><h2>Upcoming</h2><span>{botUpcoming.length}</span></header>{botUpcoming.slice(0, 3).map((item) => <div className="overview-line" key={item.job.id}><span><strong>{item.job.name}</strong><small>{item.job.schedulerSource || "Unknown source"}</small></span><span><strong>{relativeTime(item.nextRunAt)}</strong><small>{exactTime(item.nextRunAt, item.job.timezone)}</small></span></div>)}</section>}{Boolean(bot.commands?.length) && <section className="bot-overview-section"><header><h2>Commands</h2><span>{bot.commands.length}</span></header><div className="command-chips">{bot.commands.filter((command) => command.enabled !== false).map((command) => <span key={command.id || command.command}><code>{command.command}</code>{command.description}</span>)}</div></section>}{!localManaged && <section className="bot-resource-grid compact">{[["Project", "project", bot.localProjectPath], ["Repository", "repository", bot.repositoryUrl], ["Logs", "logs", bot.logsLocation], ["Deployment", "deployment", bot.deploymentUrl]].map(([label, kind, value]) => <DetailField key={kind} label={label} value={value} action={value ? <button type="button" onClick={() => api.bots.openResource(bot.id, kind)} aria-label={`Open ${label.toLowerCase()}`}><ExternalLink size={12} aria-hidden="true" /></button> : null} />)}</section>}</>}
      {tab === "activity" && <section className="bot-timeline">{activity.map((event) => <article key={event.id}><span className={`event-dot ${event.type.includes("failed") || event.type.includes("overdue") ? "danger" : ""}`}></span><div><strong>{EVENT_LABELS[event.type] || event.type.replaceAll("_", " ")}</strong><p>{event.summary}</p><small>{exactTime(event.timestamp)} · {relativeTime(event.timestamp)} · {event.source}</small></div></article>)}{!activity.length && <p className="bots-section-empty">No activity yet.</p>}<small className="retention-note">Operational events stay local. Message content is never collected.</small></section>}
      {tab === "settings" && <section className="bot-settings"><section className="bot-identity-card"><BotIcon icon={bot.icon} name={bot.name} size="large" /><span><strong>Bot icon</strong><small>Give each bot a separate symbol, color, or uploaded image.</small></span><button type="button" onClick={onEdit}>Customize Icon</button></section>{notebookLinked && <><section className="bot-link-card"><header><Link2 size={18} aria-hidden="true" /><div><h2>Private bot link</h2><p>Give this link only to agents you trust.</p></div></header><input value={botLink} readOnly aria-label="Private bot link" /><div><button type="button" onClick={copyBotLink} disabled={!botLink}><Copy size={13} aria-hidden="true" /> Copy Link</button><button type="button" onClick={resetBotLink} disabled={busy === "link"}><RefreshCw size={13} className={busy === "link" ? "spin" : ""} aria-hidden="true" /> {busy === "link" ? "Resetting…" : "Reset Link"}</button></div></section><section className="bot-permissions-card"><h2>Permissions</h2><div>{(bot.permissions || []).map((permission) => <span key={permission}><Check size={12} aria-hidden="true" /> {BOT_PERMISSION_OPTIONS.find(([id]) => id === permission)?.[1] || permission}</span>)}</div></section></>}{Boolean(bot.connections?.length) && <section className="bot-connections"><h2>Connection</h2>{bot.connections.map((connection) => <article key={connection.id}><header><span className={`platform-mark ${connection.platform}`}>{connection.platform === "discord" ? "D" : "T"}</span><div><strong>{connection.displayName || connection.username || platformLabel([connection.platform])}</strong><small>{connection.username ? `@${connection.username}` : connection.externalBotId || "Identity not verified"}</small></div><span className={`credential-state ${connection.credentialState}`}>{connection.credentialState === "verified" ? "Verified" : connection.credentialState === "invalid" ? "Invalid" : "Not verified"}</span></header>{connection.credentialErrorSummary && <p className="job-error">{connection.credentialErrorSummary}</p>}<div className="connection-actions">{connection.credentialSecretRef && <button type="button" onClick={() => verify(connection)} disabled={busy === connection.id}>{busy === connection.id ? "Verifying…" : "Verify Identity"}</button>}<button type="button" onClick={() => connection.installUrl ? api.bots.openConnectorPlatform(connection.installUrl) : api.bots.openSetup(bot.id, connection.id, "install")}>{connection.platform === "discord" ? "Install To Server" : "Open Bot"}</button></div></article>)}</section>}<section className="bot-documentation"><header><FileText size={18} aria-hidden="true" /><div><h2>Runbook</h2><p>{note?.title || "Setup, recovery, and ownership notes"}</p></div><button type="button" onClick={openDocumentation}>Open Note</button></header></section><section className="advanced-settings-card"><div><Settings2 size={16} aria-hidden="true" /><span><strong>Advanced Settings</strong><small>Monitoring, jobs, commands, deployment, and permissions</small></span></div><button type="button" onClick={onEdit}>Open Advanced Settings</button></section><button type="button" className="archive-bot" onClick={archive} disabled={busy === "archive"}><ArchiveRestore size={13} aria-hidden="true" /> {bot.archivedAt ? "Restore Bot" : "Archive Bot"}</button></section>}
    </div>
  </div>;
}

function FormField({ label, hint, wide = false, children }) {
  let control = children;
  if (React.isValidElement(children) && ["input", "select", "textarea"].includes(children.type)) {
    const controlName = String(children.props.name || children.props["aria-label"] || label).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
    const technical = /url|path|folder|reference|username|handle|application|cron|timezone|command|runtime|version/i.test(label);
    control = React.cloneElement(children, { name: controlName, autoComplete: children.props.autoComplete || "off", spellCheck: children.props.spellCheck ?? !technical });
  }
  return <label className={`bot-form-field ${wide ? "wide" : ""}`}><span>{label}</span>{control}{hint && <small>{hint}</small>}</label>;
}

function useModalKeyboard(dialogRef, onClose) {
  const closeRef = useRef(onClose); closeRef.current = onClose;
  useEffect(() => {
    const previous = document.activeElement; const dialog = dialogRef.current;
    dialog?.querySelector("input, select, textarea, button")?.focus();
    function keydown(event) {
      if (event.key === "Escape") { event.preventDefault(); closeRef.current(); return; }
      if (event.key !== "Tab" || !dialog) return;
      const focusable = [...dialog.querySelectorAll('button:not([disabled]), input:not([disabled]):not([tabindex="-1"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])')];
      if (!focusable.length) return;
      const first = focusable[0]; const last = focusable.at(-1);
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    }
    document.addEventListener("keydown", keydown);
    return () => { document.removeEventListener("keydown", keydown); previous?.focus?.(); };
  }, []);
}

function BotForm({ bot, api, skills, onCancel, onSaved }) {
  const dialogRef = useRef(null); useModalKeyboard(dialogRef, onCancel);
  const [draft, setDraft] = useState(() => editableBot(bot)); const [saving, setSaving] = useState(false); const [error, setError] = useState(""); const [testResult, setTestResult] = useState(null);
  useEffect(() => {
    const controls = dialogRef.current?.querySelectorAll("input, select, textarea") || [];
    controls.forEach((control, index) => {
      if (!control.name) control.name = String(control.getAttribute("aria-label") || control.closest("label")?.textContent || `${control.tagName}-${index}`).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
      if ((control.tagName === "INPUT" || control.tagName === "TEXTAREA") && !control.autocomplete) control.autocomplete = "off";
    });
  }, [draft.connections.length, draft.jobs.length, draft.commands.length, draft.skillIds.length]);
  const patch = (value) => setDraft((current) => ({ ...current, ...value }));
  const setMonitoring = (value) => patch({ monitoring: { ...draft.monitoring, ...value } });
  function togglePlatform(platform, enabled) {
    const platforms = enabled ? [...new Set([...draft.platforms, platform])] : draft.platforms.filter((value) => value !== platform);
    const connections = enabled ? (draft.connections.some((item) => item.platform === platform) ? draft.connections : [...draft.connections, defaultConnection(platform)]) : draft.connections.filter((item) => item.platform !== platform);
    patch({ platforms, connections });
  }
  function updateConnection(platform, value) { patch({ connections: draft.connections.map((item) => item.platform === platform ? { ...item, ...value } : item) }); }
  function updateJob(id, value) { patch({ jobs: draft.jobs.map((item) => item.id === id ? { ...item, ...value } : item) }); }
  function updateCommand(id, value) { patch({ commands: draft.commands.map((item) => item.id === id ? { ...item, ...value } : item) }); }
  function validate() {
    if (!draft.name.trim()) return "Name is required.";
    if (!draft.platforms.length) return "Select Notebook, Discord, or Telegram.";
    if (draft.platforms.includes("notebook") && !(draft.permissions || []).length) return "Choose at least one Notebook permission.";
    if (draft.executionMode === "scheduled" && !draft.jobs.some((job) => job.enabled && !job.archivedAt)) return "Scheduled bots require at least one tracked, non-archived job.";
    if (["http-health", "http-status"].includes(draft.monitoring.adapter) && !draft.monitoring.url) return "Monitoring URL is required.";
    if (draft.monitoring.adapter === "http-status" && draft.monitoring.httpMethod === "HEAD") return "Structured status monitoring requires GET so JSON can be validated.";
    if (draft.monitoring.adapter === "local-status" && !draft.monitoring.filePath) return "Status-file path is required.";
    const names = draft.jobs.map((job) => job.name.trim().toLowerCase()); if (names.some((value) => !value) || new Set(names).size !== names.length) return "Every job needs a unique name.";
    for (const job of draft.jobs) { try { cronPreview(job); } catch (reason) { return `${job.name || "Job"}: ${reason.message}`; } }
    if (draft.commands.some((command) => !command.command.trim())) return "Every documented command needs a command name.";
    return "";
  }
  async function save(event) { event.preventDefault(); const invalid = validate(); if (invalid) { setError(invalid); return; } setSaving(true); setError(""); try { const saved = bot ? await api.bots.update(bot.id, draft) : await api.bots.create(draft); await onSaved(saved); } catch (reason) { setError(reason.message || "Could not save bot."); } finally { setSaving(false); } }
  async function testMonitoring() { const invalid = validate(); if (invalid && !invalid.includes("Scheduled bots")) { setTestResult({ ok: false, error: { message: invalid } }); return; } setTestResult({ loading: true }); try { setTestResult(await api.bots.testMonitoring(draft)); } catch (reason) { setTestResult({ ok: false, error: { message: reason.message || "Monitoring test failed." } }); } }
  return <div ref={dialogRef} className="bot-form-overlay" role="dialog" aria-modal="true" aria-label="Advanced settings"><form className="bot-form" onSubmit={save}><header><div><span className="section-kicker">{bot?.name || "Bot"}</span><h1>Advanced Settings</h1><p>Monitoring, jobs, commands, deployment, and permissions.</p></div><button type="button" onClick={onCancel} aria-label="Close advanced settings"><X size={17} aria-hidden="true" /></button></header><div className="bot-form-scroll">
    {error && <p className="bot-form-error" role="alert">{error}</p>}
    <fieldset><legend>Identity</legend><BotIconPicker icon={draft.icon} name={draft.name} onChange={(icon) => patch({ icon })} /><div className="bot-form-grid bot-identity-fields"><FormField label="Name"><input value={draft.name} onChange={(event) => patch({ name: event.target.value })} aria-label="Bot name" /></FormField><FormField label="Execution mode"><select value={draft.executionMode} onChange={(event) => patch({ executionMode: event.target.value })} aria-label="Execution mode"><option value="continuous">Continuous</option><option value="scheduled">Scheduled</option><option value="webhook">Webhook</option><option value="manual">Manual</option></select></FormField><FormField label="Environment"><input value={draft.environment} onChange={(event) => patch({ environment: event.target.value })} aria-label="Bot environment" /></FormField><FormField label="Tags" hint="Comma-separated"><input value={draft.tags.join(", ")} onChange={(event) => patch({ tags: event.target.value.split(",").map((value) => value.trim()).filter(Boolean) })} aria-label="Bot tags" /></FormField><FormField label="Description" wide><textarea value={draft.description} onChange={(event) => patch({ description: event.target.value })} aria-label="Bot description" rows="3" /></FormField><div className="bot-platform-checks"><span>Platforms</span>{draft.platforms.includes("notebook") && <label><input type="checkbox" checked disabled /><span>Notebook</span></label>}{["discord", "telegram"].map((platform) => <label key={platform}><input type="checkbox" checked={draft.platforms.includes(platform)} onChange={(event) => togglePlatform(platform, event.target.checked)} /><span>{platform === "discord" ? "Discord" : "Telegram"}</span></label>)}</div></div></fieldset>
    {draft.platforms.includes("notebook") && <fieldset><legend>Notebook permissions</legend><div className="relationship-pickers"><div>{BOT_PERMISSION_OPTIONS.map(([id, label]) => <label key={id}><input type="checkbox" checked={(draft.permissions || []).includes(id)} onChange={(event) => patch({ permissions: event.target.checked ? [...new Set([...(draft.permissions || []), id])] : (draft.permissions || []).filter((value) => value !== id) })} /><span>{label}</span></label>)}</div></div></fieldset>}
    {Boolean(draft.connections.length) && <fieldset><legend>Platform connections</legend>{draft.connections.map((connection) => <div className="connection-form" key={connection.id}><header><span className={`platform-mark ${connection.platform}`}>{connection.platform === "discord" ? "D" : "T"}</span><strong>{connection.platform === "discord" ? "Discord" : "Telegram"}</strong></header><div className="bot-form-grid"><FormField label="Display name"><input value={connection.displayName || ""} onChange={(event) => updateConnection(connection.platform, { displayName: event.target.value })} aria-label={`${connection.platform} display name`} /></FormField><FormField label="Username / handle"><input value={connection.username || ""} onChange={(event) => updateConnection(connection.platform, { username: event.target.value.replace(/^@/, "") })} aria-label={`${connection.platform} username`} /></FormField><FormField label="External bot / application ID"><input value={connection.externalBotId || ""} onChange={(event) => updateConnection(connection.platform, { externalBotId: event.target.value })} aria-label={`${connection.platform} external bot ID`} /></FormField><FormField label="Credential secret reference" hint="Environment-variable name; token stays in main process"><input value={connection.credentialSecretRef || ""} onChange={(event) => updateConnection(connection.platform, { credentialSecretRef: event.target.value.toUpperCase() })} placeholder={connection.platform === "discord" ? "DISCORD_MY_BOT_TOKEN" : "TELEGRAM_MY_BOT_TOKEN"} aria-label={`${connection.platform} credential secret reference`} /></FormField>{connection.platform === "discord" && <FormField label="Install permission bitfield" hint="Request only permissions the bot needs"><input value={connection.installPermissions || "0"} onChange={(event) => updateConnection(connection.platform, { installPermissions: event.target.value })} aria-label="Discord install permissions" /></FormField>}<FormField label="Avatar URL"><input value={connection.avatarUrl || ""} onChange={(event) => updateConnection(connection.platform, { avatarUrl: event.target.value })} aria-label={`${connection.platform} avatar URL`} /></FormField></div></div>)}</fieldset>}
    <fieldset><legend>Project and deployment</legend><div className="bot-form-grid"><FormField label="Repository URL"><input value={draft.repositoryUrl || ""} onChange={(event) => patch({ repositoryUrl: event.target.value })} aria-label="Repository URL" /></FormField><FormField label="Local project folder"><input value={draft.localProjectPath || ""} onChange={(event) => patch({ localProjectPath: event.target.value })} aria-label="Local project folder" /></FormField><FormField label="Runtime / language"><input value={draft.runtime || ""} onChange={(event) => patch({ runtime: event.target.value })} aria-label="Runtime language" /></FormField><FormField label="Version"><input value={draft.version || ""} onChange={(event) => patch({ version: event.target.value })} aria-label="Bot version" /></FormField><FormField label="Hosting provider"><input value={draft.hostingProvider || ""} onChange={(event) => patch({ hostingProvider: event.target.value })} aria-label="Hosting provider" /></FormField><FormField label="Deployment URL"><input value={draft.deploymentUrl || ""} onChange={(event) => patch({ deploymentUrl: event.target.value })} aria-label="Deployment URL" /></FormField><FormField label="Logs URL or local path"><input value={draft.logsLocation || ""} onChange={(event) => patch({ logsLocation: event.target.value })} aria-label="Logs location" /></FormField><FormField label="Scheduler URL"><input value={draft.schedulerUrl || ""} onChange={(event) => patch({ schedulerUrl: event.target.value })} aria-label="Scheduler URL" /></FormField></div></fieldset>
    <fieldset><legend>Monitoring</legend><p className="fieldset-copy">Checks run only while Notebook is open. Credential verification and runtime health remain separate.</p><div className="bot-form-grid"><FormField label="Monitoring adapter"><select value={draft.monitoring.adapter} onChange={(event) => setMonitoring({ adapter: event.target.value })} aria-label="Monitoring adapter"><option value="manual">Manual / none</option><option value="http-health">Simple HTTP health</option><option value="http-status">Structured HTTP status</option><option value="local-status">Local status file</option></select></FormField>{["http-health", "http-status"].includes(draft.monitoring.adapter) && <FormField label="Status or health URL"><input value={draft.monitoring.url || ""} onChange={(event) => setMonitoring({ url: event.target.value })} aria-label="Monitoring URL" /></FormField>}{["http-health", "http-status"].includes(draft.monitoring.adapter) && <FormField label="HTTP method"><select value={draft.monitoring.httpMethod || "GET"} onChange={(event) => setMonitoring({ httpMethod: event.target.value })} aria-label="Monitoring HTTP method"><option value="GET">GET</option><option value="HEAD">HEAD</option></select></FormField>}{draft.monitoring.adapter === "local-status" && <FormField label="Status-file path"><input value={draft.monitoring.filePath || ""} onChange={(event) => setMonitoring({ filePath: event.target.value })} aria-label="Status file path" /></FormField>}<FormField label="Authentication secret reference"><input value={draft.monitoring.authSecretRef || ""} onChange={(event) => setMonitoring({ authSecretRef: event.target.value.toUpperCase() })} aria-label="Monitoring authentication secret reference" /></FormField><FormField label="Check interval (seconds)"><input type="number" min="30" max="86400" value={draft.monitoring.intervalSeconds} onChange={(event) => setMonitoring({ intervalSeconds: Number(event.target.value) })} aria-label="Check interval seconds" /></FormField><FormField label="Timeout (milliseconds)"><input type="number" min="250" max="60000" value={draft.monitoring.timeoutMilliseconds} onChange={(event) => setMonitoring({ timeoutMilliseconds: Number(event.target.value) })} aria-label="Request timeout milliseconds" /></FormField><FormField label="Stale after (seconds)"><input type="number" min="30" value={draft.monitoring.staleAfterSeconds} onChange={(event) => setMonitoring({ staleAfterSeconds: Number(event.target.value) })} aria-label="Stale threshold seconds" /></FormField><FormField label="Failures before offline"><input type="number" min="1" max="20" value={draft.monitoring.failuresBeforeOffline} onChange={(event) => setMonitoring({ failuresBeforeOffline: Number(event.target.value) })} aria-label="Failures before offline" /></FormField>{draft.monitoring.adapter === "http-health" && <FormField label="Expected HTTP code" hint="Blank accepts any 2xx"><input type="number" min="100" max="599" value={draft.monitoring.expectedResponseCode ?? ""} onChange={(event) => setMonitoring({ expectedResponseCode: event.target.value ? Number(event.target.value) : "" })} aria-label="Expected HTTP response code" /></FormField>}</div><label className="tracking-toggle"><input type="checkbox" checked={draft.monitoring.monitoringEnabled} onChange={(event) => setMonitoring({ monitoringEnabled: event.target.checked })} /><span>Monitoring enabled while Notebook is open</span></label><div className="monitor-test-row"><button type="button" onClick={testMonitoring} disabled={testResult?.loading}>{testResult?.loading ? "Testing…" : "Test monitoring"}</button>{testResult && !testResult.loading && <span className={testResult.ok ? "success" : "failed"}>{testResult.ok ? `${testResult.source} succeeded${testResult.latencyMilliseconds != null ? ` in ${testResult.latencyMilliseconds} ms` : ""}. ${testResult.parsedStatus?.state || ""} ${testResult.parsedStatus?.message || ""}` : testResult.error?.message}</span>}</div></fieldset>
    <fieldset><legend>Jobs</legend><p className="fieldset-copy">Definitions track the real scheduler. Enabled means tracked here; Notebook does not start, stop, or reschedule the real job.</p>{draft.jobs.map((job) => { let preview; let previewError; try { preview = cronPreview(job); } catch (reason) { previewError = reason.message; } return <div className="job-form" key={job.id}><header><input value={job.name} onChange={(event) => updateJob(job.id, { name: event.target.value })} placeholder="Job name" aria-label="Job name" />{job.createdAt ? <button type="button" onClick={() => updateJob(job.id, { archivedAt: job.archivedAt ? null : new Date().toISOString() })} aria-label={`${job.archivedAt ? "Restore" : "Archive"} ${job.name || "job"}`}><ArchiveRestore size={14} /></button> : <button type="button" onClick={() => patch({ jobs: draft.jobs.filter((item) => item.id !== job.id) })} aria-label={`Remove ${job.name || "job"}`}><X size={14} /></button>}</header><div className="bot-form-grid"><FormField label="Schedule type"><select value={job.scheduleType} onChange={(event) => updateJob(job.id, { scheduleType: event.target.value })} aria-label={`Schedule type for ${job.name || "job"}`}><option value="cron">Cron</option><option value="interval">Interval</option><option value="oneTime">One time</option><option value="external">External</option><option value="manual">Manual</option></select></FormField>{job.scheduleType === "cron" && <><FormField label="Cron expression"><input value={job.cronExpression || ""} onChange={(event) => updateJob(job.id, { cronExpression: event.target.value })} aria-label={`Cron expression for ${job.name || "job"}`} /></FormField><FormField label="IANA timezone"><input value={job.timezone || ""} onChange={(event) => updateJob(job.id, { timezone: event.target.value })} aria-label={`Timezone for ${job.name || "job"}`} /></FormField></>}{job.scheduleType === "interval" && <FormField label="Interval seconds"><input type="number" min="1" value={job.intervalSeconds || ""} onChange={(event) => updateJob(job.id, { intervalSeconds: Number(event.target.value) })} aria-label={`Interval for ${job.name || "job"}`} /></FormField>}{job.scheduleType === "oneTime" && <FormField label="One-time ISO date"><input value={job.oneTimeAt || ""} onChange={(event) => updateJob(job.id, { oneTimeAt: event.target.value })} placeholder="2026-08-18T14:00:00.000Z" aria-label={`One time date for ${job.name || "job"}`} /></FormField>}<FormField label="Scheduler source"><select value={job.schedulerSource} onChange={(event) => updateJob(job.id, { schedulerSource: event.target.value })} aria-label={`Scheduler source for ${job.name || "job"}`}>{SCHEDULER_SOURCES.map((value) => <option key={value}>{value}</option>)}</select></FormField><FormField label="Grace period seconds"><input type="number" min="0" value={job.gracePeriodSeconds ?? 0} onChange={(event) => updateJob(job.id, { gracePeriodSeconds: Number(event.target.value) })} aria-label={`Grace period for ${job.name || "job"}`} /></FormField><FormField label="Expected duration seconds"><input type="number" min="1" value={job.expectedDurationSeconds || ""} onChange={(event) => updateJob(job.id, { expectedDurationSeconds: Number(event.target.value) })} aria-label={`Expected duration for ${job.name || "job"}`} /></FormField><FormField label="Description" wide><textarea value={job.description || ""} onChange={(event) => updateJob(job.id, { description: event.target.value })} aria-label={`Description for ${job.name || "job"}`} rows="2" /></FormField></div><div className={`schedule-preview ${previewError ? "failed" : ""}`}><strong>{previewError ? "Invalid schedule" : "Next three occurrences"}</strong>{previewError ? <span>{previewError}</span> : preview.values.length ? preview.values.map((value) => <span key={value}>{exactTime(value, job.timezone)} · {job.timezone}</span>) : <span>{preview.label}</span>}</div><div className="job-toggles"><label><input type="checkbox" checked={job.enabled} onChange={(event) => updateJob(job.id, { enabled: event.target.checked })} /> Track job</label><label><input type="checkbox" checked={job.critical} onChange={(event) => updateJob(job.id, { critical: event.target.checked })} /> Critical job</label>{job.archivedAt && <span>Archived definition; history retained</span>}</div></div>; })}<button type="button" className="add-inline" onClick={() => patch({ jobs: [...draft.jobs, defaultJob(Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC")] })}><Plus size={13} /> Add job</button></fieldset>
    <fieldset><legend>Commands</legend>{draft.commands.map((command) => <div className="command-form" key={command.id}><header><input value={command.command} onChange={(event) => updateCommand(command.id, { command: event.target.value })} placeholder="/command" aria-label="Command name" /><select value={command.platform} onChange={(event) => updateCommand(command.id, { platform: event.target.value })} aria-label={`Platform for ${command.command || "command"}`}>{draft.platforms.map((platform) => <option key={platform}>{platform}</option>)}</select><button type="button" onClick={() => patch({ commands: draft.commands.filter((item) => item.id !== command.id) })} aria-label={`Remove ${command.command || "command"}`}><X size={14} /></button></header><div className="bot-form-grid"><FormField label="Description"><input value={command.description || ""} onChange={(event) => updateCommand(command.id, { description: event.target.value })} aria-label={`Description for ${command.command || "command"}`} /></FormField><FormField label="Usage"><input value={command.usage || ""} onChange={(event) => updateCommand(command.id, { usage: event.target.value })} aria-label={`Usage for ${command.command || "command"}`} /></FormField><FormField label="Parameters"><input value={command.parameters || ""} onChange={(event) => updateCommand(command.id, { parameters: event.target.value })} aria-label={`Parameters for ${command.command || "command"}`} /></FormField><FormField label="Permission"><input value={command.permission || ""} onChange={(event) => updateCommand(command.id, { permission: event.target.value })} aria-label={`Permission for ${command.command || "command"}`} /></FormField><FormField label="Category"><input value={command.category || ""} onChange={(event) => updateCommand(command.id, { category: event.target.value })} aria-label={`Category for ${command.command || "command"}`} /></FormField><FormField label="Notes" wide><textarea value={command.notes || ""} onChange={(event) => updateCommand(command.id, { notes: event.target.value })} aria-label={`Notes for ${command.command || "command"}`} rows="2" /></FormField></div><div className="job-toggles"><label><input type="checkbox" checked={command.enabled !== false} onChange={(event) => updateCommand(command.id, { enabled: event.target.checked })} /> Enabled</label><label><input type="checkbox" checked={Boolean(command.deprecated)} onChange={(event) => updateCommand(command.id, { deprecated: event.target.checked })} /> Deprecated</label></div></div>)}<button type="button" className="add-inline" onClick={() => patch({ commands: [...draft.commands, defaultCommand(draft.platforms[0])] })}><Plus size={13} /> Add command</button></fieldset>
    <fieldset><legend>Skills</legend><div className="relationship-pickers"><div>{skills.map((skill) => <label key={skill.id}><input type="checkbox" checked={draft.skillIds.includes(skill.id)} onChange={(event) => patch({ skillIds: event.target.checked ? [...draft.skillIds, skill.id] : draft.skillIds.filter((id) => id !== skill.id) })} /><span>{skill.name || "Untitled skill"}</span></label>)}</div></div></fieldset>
    <fieldset><legend>Documentation</legend><p className="fieldset-copy">Saving creates or keeps one Markdown note with purpose, setup, development, deployment, recovery, troubleshooting, logs, and ownership sections. Existing note content is preserved.</p></fieldset>
  </div><footer><button type="button" onClick={onCancel}>Cancel</button><button type="submit" disabled={saving}>{saving ? "Saving…" : bot ? "Save changes" : "Add bot"}</button></footer></form></div>;
}

export function BotsWorkspace({ api, bots, skills, notes, currentId, onCurrent, onBotsChange, onNotesChange, onOpenNote, onOpenSkill, onHide }) {
  const [loading, setLoading] = useState(true); const [upcoming, setUpcoming] = useState([]); const [formBot, setFormBot] = useState(null); const [formOpen, setFormOpen] = useState(false); const [createOpen, setCreateOpen] = useState(false); const [refreshing, setRefreshing] = useState(false); const [refreshMessage, setRefreshMessage] = useState("");
  const selected = bots.find((bot) => bot.id === currentId) || null;
  async function reload() { const [savedUpcoming] = await Promise.all([api.bots.upcoming(50), onBotsChange()]); setUpcoming(savedUpcoming); setLoading(false); }
  useEffect(() => { reload().catch(() => { setLoading(false); setRefreshMessage("Could not load bot operations."); }); }, []);
  useEffect(() => { api.bots.upcoming(50).then(setUpcoming).catch(() => {}); }, [bots]);
  async function refreshAll() { if (refreshing) return; setRefreshing(true); setRefreshMessage("Checking configured bots…"); try { const result = await api.bots.checkAll(); await reload(); setRefreshMessage(`Checked ${result.checked}: ${result.succeeded} succeeded, ${result.failed} failed.`); } catch (reason) { setRefreshMessage(reason.message || "Refresh failed."); } finally { setRefreshing(false); } }
  function openForm(bot) { setFormBot(bot); setFormOpen(true); }
  async function saved(bot) { setFormOpen(false); await Promise.all([reload(), onNotesChange?.()]); onCurrent(bot.id); }
  async function quickCreated(result) { await Promise.all([reload(), onNotesChange?.()]); setRefreshMessage(`${result.bot.name} created.`); }
  if (loading) return <section className="bots-page bots-loading"><header><div><span className="section-kicker">Automation</span><h1>Bots</h1><p>Loading local registry and operational state…</p></div></header><div className="bots-skeleton"></div></section>;
  if (selected) return <section className="bots-page"><BotDetails bot={selected} api={api} notes={notes} upcoming={upcoming} onBack={() => onCurrent(null)} onEdit={() => openForm(selected)} onChanged={reload} onOpenNote={onOpenNote} />{formOpen && <BotForm bot={formBot} api={api} skills={skills} onCancel={() => setFormOpen(false)} onSaved={saved} />}</section>;
  return <section className="bots-page"><header className="bots-page-header"><div><span className="section-kicker">Automation</span><h1>Bots</h1><p>Create Notebook bots with private, resettable links.</p></div><div><button type="button" onClick={refreshAll} disabled={refreshing}><RefreshCw size={13} className={refreshing ? "spin" : ""} aria-hidden="true" /> {refreshing ? "Refreshing…" : "Refresh"}</button><button type="button" className="primary" onClick={() => setCreateOpen(true)}><Plus size={13} aria-hidden="true" /> Create Bot</button><button type="button" className="hide" onClick={onHide} aria-label="Hide notebook">×</button></div></header>{refreshMessage && <p className="bot-refresh-message" role="status" aria-live="polite">{refreshMessage}</p>}<div className="bots-page-scroll">{!bots.length ? <div className="bot-empty"><Bot size={28} aria-hidden="true" /><strong>Create Your First Bot</strong><span>Add a name, description, logo, and permissions. Notebook handles the rest.</span><button type="button" onClick={() => setCreateOpen(true)}><Plus size={14} aria-hidden="true" /> Create Bot</button></div> : <><AttentionArea bots={bots} onOpen={onCurrent} />{Boolean(upcoming.length) && <UpcomingJobs upcoming={upcoming} onOpen={onCurrent} />}<BotRegistry bots={bots} upcoming={upcoming} onOpen={onCurrent} onAdd={() => setCreateOpen(true)} /></>}</div>{createOpen && <BotCreateDialog api={api} onClose={() => setCreateOpen(false)} onCreated={quickCreated} onOpenBot={(bot) => { setCreateOpen(false); onCurrent(bot.id); }} />}</section>;
}
